import yaml
import os

ALLOWED_EXTENSIONS = {'.yaml', '.yml'}
ALLOWED_PATHS = ['/allowed/path1', '/allowed/path2']
FILE_SIZE_LIMIT = 1024 * 1024  # 1 MB

def log_error(error_message):
    print(f"Error: {error_message}")  # Placeholder for actual logging

def is_valid_filename(filename):
    return os.path.splitext(filename)[1] in ALLOWED_EXTENSIONS

def is_within_allowed_paths(filepath):
    return any(filepath.startswith(path) for path in ALLOWED_PATHS)

def is_file_size_within_limit(filepath):
    return os.path.getsize(filepath) <= FILE_SIZE_LIMIT

def yaml_load(filename):
    try:
        if not is_valid_filename(filename):
            raise ValueError("Invalid file extension.")

        abs_path = os.path.abspath(filename)

        if not is_within_allowed_paths(abs_path):
            raise ValueError("File path is not allowed.")

        if not os.path.isfile(abs_path):
            raise FileNotFoundError("File not found.")

        if not is_file_size_within_limit(abs_path):
            raise ValueError("File size exceeds limit.")

        with open(abs_path, 'r') as file:
            return yaml.safe_load(file)

    except FileNotFoundError as e:
        log_error(e)
        return None
    except yaml.YAMLError as e:
        log_error(e)
        return None
    except ValueError as e:
        log_error(e)
        return None

