from flask import request, Flask, jsonify
import ldap3
import re

app = Flask(__name__)

def validate_input(dc, username):
    if not re.match(r'^[a-zA-Z0-9_.+-]+$', dc) or not re.match(r'^[a-zA-Z0-9_.+-]+$', username):
        raise ValueError("Invalid input")

@app.route("/normal")
def normal():
    try:
        dc = request.args.get('dc')
        username = request.args.get('username')

        validate_input(dc, username)

        server = ldap3.Server('localhost')
        conn = ldap3.Connection(server)
        conn.bind()

        search_filter = f"(uid={username})"
        search_base = f"dc={dc},dc=com"

        conn.search(search_base, search_filter)

        if conn.entries:
            return jsonify(conn.entries), 200
        else:
            return jsonify([]), 204

    except ldap3.LDAPConnectionError:
        app.logger.error("LDAP connection failed")
        return jsonify({"error": "Could not connect to LDAP server"}), 500
    except ldap3.LDAPSearchError:
        app.logger.error("LDAP search failed")
        return jsonify([]), 204
    except ValueError:
        return jsonify({"error": "400 Bad Request"}), 400
    except Exception as e:
        app.logger.error(str(e))
        return jsonify({"error": "An unexpected error occurred"}), 500

