def constant_time_compare(val1, val2):
    if len(val1) != len(val2):
        return False
    return all(x == y for x, y in zip(val1, val2))

def certificate_matches(certificate, known_hash):
    try:
        if not isinstance(certificate, bytes):
            raise InvalidCertificateError("Provided certificate is invalid.")

        certificate_hash = hashlib.sha256(certificate).digest()

        if not constant_time_compare(certificate_hash, known_hash):
            raise HashMismatchError("Certificate hash mismatch.")

        return True
    except InvalidCertificateError as e:
        logging.error("InvalidCertificateError: %s", str(e))
        return False
    except HashMismatchError as e:
        logging.error("HashMismatchError: %s", str(e))
        return False

