import secrets
import string

def generateRandomString(length):
    if length <= 0:
        raise ValueError("Length must be a positive integer.")
    secure_random = secrets.token_urlsafe(length)
    filtered_string = ''.join(filter(lambda x: x in string.ascii_letters, secure_random))
    if len(filtered_string) < length:
        filtered_string += secrets.token_urlsafe(length - len(filtered_string))
    filtered_string = ''.join(filter(lambda x: x in string.ascii_letters, filtered_string))
    return filtered_string[:length] if len(filtered_string) >= length else generateRandomString(length)

