from lxml import etree
from django.http import HttpResponse

def xpath_query(request):
    xpath = request.GET.get('xpath')
    xml_input = request.GET.get('xml')

    if not xpath or not xml_input:
        return HttpResponse('Invalid input', status=400)

    try:
        parser = etree.XMLParser(resolve_entities=False)
        xml_tree = etree.fromstring(xml_input.encode(), parser)
    except ValueError:
        return HttpResponse('Invalid input', status=400)
    except etree.XMLSyntaxError:
        return HttpResponse('Malformed XML', status=400)

    try:
        xpath_expr = etree.XPath(xpath)
        result = xpath_expr(xml_tree)
    except etree.XPathEvalError:
        return HttpResponse('XPath evaluation error', status=400)

    encoded_result = [etree.tostring(e).decode('utf-8') for e in result]
    return HttpResponse(''.join(encoded_result))

