from flask import Flask, request, jsonify, make_response
from functools import wraps
import time

app = Flask(__name__)

USER_ID_REGEX = r'^[a-zA-Z0-9_]+$'  # Define a regex pattern for user IDs
RATE_LIMIT = 100  # Define a rate limit for API requests
request_count = {}
request_time = {}

def rate_limit(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        remote_addr = request.remote_addr
        current_time = time.time()
        if remote_addr not in request_count:
            request_count[remote_addr] = 0
            request_time[remote_addr] = current_time
        if current_time - request_time[remote_addr] > 60:  # reset count every minute
            request_count[remote_addr] = 0
            request_time[remote_addr] = current_time
        request_count[remote_addr] += 1
        if request_count[remote_addr] > RATE_LIMIT:
            return make_response(jsonify({"error": "Too Many Requests"}), 429)
        return f(*args, **kwargs)
    return decorated_function

@app.route("/user")
@rate_limit
def retrieve_info():
    user_id = request.args.get('user_id')
    auth_token = request.headers.get('Authorization')

    try:
        if not re.match(USER_ID_REGEX, user_id):
            raise ValueError("Invalid User ID")

        if not auth_token:
            return make_response(jsonify({"error": "Authentication token is required"}), 401)

        response = requests.get(f"https://api.github.com/users/{user_id}", headers={"Authorization": auth_token}, timeout=5)
        response.raise_for_status()

        user_info = response.json()
        sanitized_info = {key: user_info[key] for key in ['login', 'id', 'avatar_url']}  # Sanitize response
        return jsonify(sanitized_info)

    except ValueError:
        return make_response(jsonify({"error": "400 Bad Request"}), 400)
    except requests.exceptions.RequestException:
        return make_response(jsonify({"error": "502 Bad Gateway"}), 502)
    except KeyError:
        return make_response(jsonify({"error": "404 Not Found"}), 404)

