from botocore.exceptions import ClientError

DYNAMO_CLIENT = boto3.client('dynamodb')

MAX_LOGIN_ATTEMPTS = 5
login_attempts = {}

def getUser(username, password):
    global login_attempts
    if username not in login_attempts:
        login_attempts[username] = 0

    if login_attempts[username] >= MAX_LOGIN_ATTEMPTS:
        return "Maximum login attempts exceeded. Please try again later."

    try:
        response = DYNAMO_CLIENT.get_item(
            TableName='users',
            Key={'username': {'S': username}}
        )

        if 'Item' not in response:
            login_attempts[username] += 1
            return "Invalid username or password."

        user_data = response['Item']
        hashed_password = user_data['password']['S'].encode('utf-8')

        if bcrypt.checkpw(password.encode('utf-8'), hashed_password):
            login_attempts[username] = 0
            return json.loads(user_data['info']['S'])
        else:
            login_attempts[username] += 1
            return "Invalid username or password."

    except ClientError as e:
        logging.error(f"ClientError: {e}")
        return "An error occurred while retrieving user data."
    except ValueError:
        return "An unexpected error occurred. Please try again."
